"""The Grafana dashboards (deploy/observability/grafana/dashboards): generated by build_dashboards.py and committed
unchanged, well-formed Grafana JSON, and every panel explained in docs/operations/observability.md."""

from __future__ import annotations

from typing import Any

from tests.unit.observability import sources

PANEL_TYPES = {"row", "timeseries", "stat"}
DATASOURCE = {"type": "prometheus", "uid": "${datasource}"}


def test_committed_dashboards_equal_the_builder_output() -> None:
    expected = sources.builder().render()
    committed = {p.name: p.read_text() for p in sorted(sources.DASHBOARD_DIR.glob("*.json"))}
    assert committed == expected, "regenerate them: make observability-dashboards"


def test_dashboard_structure() -> None:
    dashes = sources.dashboards()
    uids = [d["uid"] for d in dashes.values()]
    assert len(set(uids)) == len(uids) == 7
    for file, d in dashes.items():
        assert file == f"{d['uid']}.json" and d["uid"].startswith("noema-") and len(d["uid"]) <= 40
        assert d["title"].startswith("Noema / ") and d["description"] and "noema" in d["tags"]
        assert isinstance(d["schemaVersion"], int)
        variables = {v["name"]: v for v in d["templating"]["list"]}
        assert variables["datasource"]["type"] == "datasource" and variables["datasource"]["query"] == "prometheus"
        ids = [p["id"] for p in d["panels"]]
        assert len(set(ids)) == len(ids), file
        _assert_no_overlap(file, d["panels"])
        assert d["panels"][0]["type"] == "row", file


def test_every_panel_is_complete() -> None:
    problems = []
    for file, d in sources.dashboards().items():
        for p in d["panels"]:
            where = f"{file}: {p.get('title')}"
            if p["type"] not in PANEL_TYPES:
                problems.append(f"{where}: panel type {p['type']}")
            if p["type"] == "row":
                continue
            if not p.get("description") or p.get("datasource") != DATASOURCE:
                problems.append(f"{where}: description and the ${{datasource}} variable are required")
            refs = [t["refId"] for t in p["targets"]]
            if not refs or len(set(refs)) != len(refs):
                problems.append(f"{where}: targets need unique refIds")
            problems += [f"{where}: target {t['refId']} is malformed" for t in p["targets"] if not _well_formed(t)]
            if p["fieldConfig"]["defaults"].get("unit") is None:
                problems.append(f"{where}: no unit")
    assert not problems


def test_panel_titles_are_unique_per_dashboard_and_documented() -> None:
    doc = sources.DOC.read_text()
    missing = []
    for file, d in sources.dashboards().items():
        titles = [p["title"] for p in d["panels"]]
        assert len(set(titles)) == len(titles), file
        assert d["title"] in doc, f"{d['title']} is not in {sources.DOC.name}"
        missing += [f"{file}: {p['title']}" for p in sources.panels(d) if f"| {p['title']} |" not in doc]
    assert not missing, f"not in {sources.DOC.name}: {missing}"


def _well_formed(target: dict[str, Any]) -> bool:
    expr = target["expr"]
    return bool(expr.strip()) and target["datasource"] == DATASOURCE and expr.count("(") == expr.count(")")


def _assert_no_overlap(file: str, panels: list[dict[str, Any]]) -> None:
    cells: set[tuple[int, int]] = set()
    for p in panels:
        g = p["gridPos"]
        assert g["x"] >= 0 and g["x"] + g["w"] <= 24, f"{file}: {p['title']} is outside the 24-column grid"
        mine = {(x, y) for x in range(g["x"], g["x"] + g["w"]) for y in range(g["y"], g["y"] + g["h"])}
        assert not cells & mine, f"{file}: {p['title']} overlaps another panel"
        cells |= mine
